/**
 * Canonical file storage abstraction. Generated by scaffold-upload-module
 * (when the project has any `uploads:` in MODULE_PLAN.yaml).
 *
 * Two adapters ship out of the box:
 *   - LocalFileStorageService  (filesystem under STORAGE_LOCAL_DIR)
 *   - S3FileStorageService     (AWS S3 / S3-compatible — uses @aws-sdk/client-s3)
 *
 * Selected at runtime by STORAGE_DRIVER env var (`local` | `s3`).
 */
export interface FileStorageUploadResult {
  /** Opaque key/path the storage backend uses to retrieve the file later. */
  storageKey: string;
  /** Public-or-signed URL the client can use to download. May be null if
   *  the adapter requires a separate `getDownloadUrl()` call. */
  url: string | null;
  size: number;
  mimeType: string;
}

export interface IFileStorageService {
  upload(opts: {
    bucket?: string;
    key: string;
    body: Buffer;
    mimeType: string;
  }): Promise<FileStorageUploadResult>;

  delete(opts: { bucket?: string; key: string }): Promise<void>;

  getDownloadUrl(opts: {
    bucket?: string;
    key: string;
    expiresInSeconds?: number;
  }): Promise<string>;
}

export const FILE_STORAGE = Symbol('FILE_STORAGE');
